mapper.select:
SELECT distinct
A.ACCT_NO id,
B.SEC_ACCT_NAME text
FROM PTL_SEC_ACCT A
INNER JOIN STL_SEC_ACCT_INFO B
ON A.ACCT_NO = B.SEC_ACCT_ID

    LEFT JOIN FIN_PRODUCT FP
    ON FP.FINPROD_ID IN (

        #{item}

    )



        AND A.PORTFOLIO_ID IN(

            #{item}

        )


        AND
        (
        A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
        OR
        B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
        )


        AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR
        (PORTFOLIO_ID || A.ACCT_NO) = #{initValue, jdbcType=VARCHAR}
        )


        AND B.TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}


        AND B.TRADE_PLACE = FP.TRADE_MARKET

sql.where:
T1.CCY = 'CNY'
AND T1.VDATE <= #{platDate,jdbcType=DATE}
AND T1.MDATE >= #{platDate,jdbcType=DATE}
AND (mbmi.MARKET_AMT > 0 OR mbmi.MARKET_AMT IS NULL )
AND T1.FINPROD_TYPE2 = #{assestType}
AND T1.TRADE_MARKET in(#{TRADE_PLACE_01},#{TRADE_PLACE_02},#{TRADE_PLACE_03},#{TRADE_PLACE_09},#{TRADE_PLACE_04})

    and T1.FINPROD_MARKET_ID = #{initValue}


    and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
    or T1.FINPROD_NAME like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ABBR like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ID like concat('%',concat(#{search},'%'))
    )

T1.CCY = 'CNY'
AND T1.VDATE <= #{platDate,jdbcType=DATE}
AND T1.MDATE >= #{platDate,jdbcType=DATE}
AND (mbmi.MARKET_AMT > 0 OR mbmi.MARKET_AMT IS NULL )
AND T1.FINPROD_TYPE2 = #{assestType}
AND T1.TRADE_MARKET in(#{TRADE_PLACE_01},#{TRADE_PLACE_02})

    and T1.FINPROD_MARKET_ID = #{initValue}


    and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
    or T1.FINPROD_NAME like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ABBR like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ID like concat('%',concat(#{search},'%'))
    )

mapper.select:
SELECT distinct T1.FINPROD_MARKET_ID id, T1.FINPROD_ABBR text, T1.FINPROD_ID FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_BOND_MARKET_INFO mbmi ON T1.FINPROD_MARKET_ID = mbmi.SEC_ID AND mbmi.VALUE_DATE = #{platDate,jdbcType=DATE}
union all select distinct T1.item_code id, T1.item_value text, T1.item_code as FINPROD_ID from sys_datadict_list T1 where T1.dict_code='TERM_TYPE_REBACK'
and T1.item_code = #{initValue}
and (T1.item_code like concat('%',concat(#{search},'%')) or T1.item_value like concat('%',concat(#{search},'%')) )

SELECT distinct T1.FINPROD_MARKET_ID id, T1.FINPROD_ABBR text, T1.FINPROD_ID FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_BOND_MARKET_INFO mbmi ON T1.FINPROD_MARKET_ID = mbmi.SEC_ID AND mbmi.VALUE_DATE = #{platDate,jdbcType=DATE}
union all select distinct T1.item_code id, T1.item_value text, T1.item_code as FINPROD_ID from sys_datadict_list T1 where T1.dict_code='TERM_TYPE_REBACK'
and T1.item_code = #{initValue}
and (T1.item_code like concat('%',concat(#{search},'%')) or T1.item_value like concat('%',concat(#{search},'%')) )
union all select distinct T1.FINPROD_MARKET_ID id, T1.FINPROD_ABBR text, T1.FINPROD_ID from FIN_PRODUCT T1 where T1.FINPROD_TYPE2 IN ('F18', 'F06', 'F17', 'F07','F32') AND T1.CCY = 'CNY'
and T1.FINPROD_MARKET_ID = #{initValue}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')) or T1.FINPROD_ABBR like concat('%',concat(#{search},'%')) or T1.FINPROD_ID like concat('%',concat(#{search},'%')) )

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object, A.PROFIT_TYPE col FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON A.PORTFOLIO_ID = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
A.VDATE <= #{platDate,jdbcType=DATE} AND A.PORTFOLIO_ID NOT IN (SELECT DISTINCT TFP.PORTFOLIO_ID PORTFOLIO_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFP WHERE (TFP.PS = 'C5' OR TFP.PS = 'C20') AND (TFP.IS_CANCEL !='Y' OR TFP.IS_CANCEL IS NULL) )
AND (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}

SELECT distinct T1.FINPROD_MARKET_ID id, T1.FINPROD_ABBR text, T1.FINPROD_NAME, T1.FINPROD_ID, T1.CALENDAR_ID, T1.TRADE_MARKET, T1.IS_RIGHT, T2.TYPE_9, T2.TYPE_10, T2.TYPE_11, to_char(T1.VDATE,'yyyy-MM-dd') VDATE, to_char(T1.MDATE, 'yyyy-MM-dd') MDATE, T1.CCY, pr.price as PRICE, to_char(pr.exercise_date,'yyyy-MM-dd') EXERCISE_DATE, to_char(pr.act_exercise_date, 'yyyy-MM-dd') ACT_EXERCISE_DATE from ptl_sec_position_rule ptl
INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ptl.PORTFOLIO_ID = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
inner join fin_product T1 on ptl.finprod_id=T1.finprod_id and T1.is_right='Y' and T1.CCY = 'CNY' LEFT JOIN MST_BOND_MARKET_INFO mbmi ON T1.FINPROD_MARKET_ID = mbmi.SEC_ID AND mbmi.VALUE_DATE = #{platDate,jdbcType=DATE}
inner join ( select row_number() over(partition by pd.finprod_id order by pd.exercise_date) idx, pd.finprod_id, pd.exercise_price as price, pd.exercise_date, pd.act_exercise_date from FIN_EXERCISE_PLAN pd where pd.exercise_date>#{platDate}
and pd.exercise_type='02'
and pd.exercise_type='01'
)pr on pr.finprod_id=T1.finprod_id and pr.finprod_id=ptl.finprod_id and pr.idx=1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID where T1.FINPROD_TYPE2 = #{assestType} AND T1.VDATE <= #{platDate,jdbcType=DATE} AND T1.MDATE >= #{platDate,jdbcType=DATE} AND (mbmi.MARKET_AMT > 0 OR mbmi.MARKET_AMT IS NULL ) AND T1.TRADE_MARKET in(#{TRADE_PLACE_01},#{TRADE_PLACE_02}) and T1.is_right='Y' and ptl.cdate=#{platDate}
and ptl.amount>0
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')) or T1.FINPROD_ABBR like concat('%',concat(#{search},'%')) or T1.FINPROD_ID like concat('%',concat(#{search},'%')) )

SELECT DISTINCT MST_CFETS_CUSTOMER_INFO.PARTY_ID id, MST_CFETS_CUSTOMER_INFO.PARTY_ABBR text, MST_CFETS_CUSTOMER_INFO.PARTY_ID as object FROM MST_CFETS_CUSTOMER_INFO inner join MST_COUNTER_PARTY mst on MST_CFETS_CUSTOMER_INFO.party_id=mst.party_id
AND (MST_CFETS_CUSTOMER_INFO.PARTY_ID like concat('%',concat(#{search},'%')) or MST_CFETS_CUSTOMER_INFO.PARTY_ABBR like concat('%',concat(#{search},'%')))
AND MST_CFETS_CUSTOMER_INFO.PARTY_ID =#{initValue}

select distinct I.Counterinstitutioncode id, mstc.PARTY_ABBR text, mstc.party_id as object from INTERF_CSTP_TRADE I inner join MST_CFETS_CUSTOMER_INFO mstc on mstc.party_customer_id=I.Counterinstitutioncode where I.Counterinstitutioncode is not null
AND (I.Counterinstitutioncode like concat('%',concat(#{search},'%')) or mstc.PARTY_ABBR like concat('%',concat(#{search},'%')))
AND to_date(I.Tradedate,'yyyy-MM-dd')= #{sysDate,jdbcType=DATE}
AND mstc.party_id in
#{item}

select distinct I.OURINSTITUTIONCODE id, mstc.PARTY_ABBR text, mstc.party_id as object from INTERF_CSTP_TRADE I inner join MST_CFETS_CUSTOMER_INFO mstc on mstc.party_customer_id=I.OURINSTITUTIONCODE where I.OURINSTITUTIONCODE is not null
AND to_date(I.Tradedate,'yyyy-MM-dd')= #{sysDate,jdbcType=DATE}
AND (I.OURINSTITUTIONCODE like concat('%',concat(#{search},'%')) or mstc.PARTY_ABBR like concat('%',concat(#{search},'%')))

select distinct mst.counter_id id,mst.counter_name text,mst.party_id as object from MST_COUNTER_PARTY mst where mst.counter_type in ('01','02')
AND (mst.counter_id like concat('%',concat(#{search},'%')) or mst.counter_name like concat('%',concat(#{search},'%')))
AND mst.counter_id =#{initValue}
AND mst.party_id in
#{item}

SELECT distinct MST_CFETS_CUSTOMER_TRADER.TRADER_ID id, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME text, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID parentId FROM (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN( SELECT nvl(t2.mparty_id,t1.party_id) PARTY_ID from MST_CFETS_CUSTOMER_INFO t1 LEFT JOIN MST_CFETS_CUSTOMER_RELA t2 on t1.party_id = t2.sparty_id WHERE 1 = 1
AND t1.PARTY_ID = #{partyId}
) t3 on MST_CFETS_CUSTOMER_TRADER.PARTY_ID = t3.PARTY_ID ) MST_CFETS_CUSTOMER_TRADER WHERE 1 = 1
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{search},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{search},'%')))
AND MST_CFETS_CUSTOMER_TRADER.TRADER_ID = #{initValue}

select mcct.TRADER_ID id, mcct.TRADER_NAME text, mcct.MPARTY_ID parentId from MST_CFETS_CUSTOMER_TRADER mcct left join MST_COUNTER_PARTY mcp on mcct.PARTY_ID = mcp.PARTY_ID
AND mcp.COUNTER_ID = #{partyId}
AND (mcct.TRADER_ID like concat('%',concat(#{search},'%')) or mcct.TRADER_NAME like concat('%',concat(#{search},'%')))

select
SUM(AMOUNT)
from PTL_CASH_POSITION_FLOW
where CDATE <= #{cdate,jdbcType=DATE}


    and ACCT_ID in (
    SELECT ACCT_NO from PTL_CAPACCT_INFO where PORTFOLIO_ID = #{portfolioId}
    #{item}
    )

and (is_exist_new is null or is_exist_new != 'Y')

