    #{item}
    )

select
sum(t.amount) as amount
from ETR_CASH_POSITION_flow t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.acct_id = #{acctId,jdbcType=VARCHAR}


    and t.chl_finprod_id = #{chlFinprodId,jdbcType=VARCHAR}

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate  <= #{cdate,jdbcType=DATE}
and t.ccy = #{ccy,jdbcType=VARCHAR}

    and t.acct_id in (
    select t1.acct_no from ptl_capacct_info t1
    where t1.acct_type in

        #{item}

    and t1.portfolio_id = #{portfolioId,jdbcType=VARCHAR}
    )

and (t.is_exist_new is null or t.is_exist_new != 'Y')

