select distinct decode(B.ELEMENT_ID, 'null', B.PAGE_ID, '', B.PAGE_ID, B.ELEMENT_ID)
from SYS_ROLE_MODULE B,
     SYS_USER A
where A.ADMIN_FLAG = '01'
  and A.USER_NAME = #{userName, jdbcType=VARCHAR}
